def test_from_dotdot_pkg_import_y_resolves_across_packages(tmp_path):
    # ``from ..pkg import y`` inside top/outer/user.py must resolve to
    # top.pkg.y (one package up from top/outer, then into pkg).
    root = make_project(tmp_path, {
        "top/__init__.py": "",
        "top/outer/__init__.py": "",
        "top/pkg/__init__.py": "",
        "top/pkg/y.py": "Y = 42\n",
        "top/outer/user.py":
            "from ..pkg import y\n\ndef get():\n    return y.Y\n",
    })
    edges, _ = import_graph.build_graph(root)
    assert edges["top.outer.user"] == {"top.pkg.y"}


def test_dotdot_y_imports_sibling_of_grandparent_package(tmp_path):
    # ``from ..y import Y`` from top/inner/mod.py -> top.y
    root = make_project(tmp_path, {
        "top/__init__.py": "",
        "top/inner/__init__.py": "",
        "top/y.py": "Y = 42\n",
        "top/inner/consumer.py":
            "from ..y import Y\n\ndef get():\n    return Y\n",
    })
    edges, _ = import_graph.build_graph(root)
    assert edges["top.inner.consumer"] == {"top.y"}
